INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "杜孺休", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：杜孺休。", "biography": null, "status": "draft", "id": "b78e915f-93b3-5b05-b03f-4dfb246232d7"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "沈粲", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：沈粲。", "biography": null, "status": "draft", "id": "080ea532-6021-504d-a8b9-895f563514f5"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "李友", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：李友。", "biography": null, "status": "draft", "id": "a1f641f7-aecb-5557-a85e-f9062ae83c1d"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "status": "draft", "id": "4426793f-0bd8-5a79-919f-7e3a0ddae520"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "陈敬瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的陈敬瑄：此前许诺以东川酬赏高仁厚。", "biography": null, "status": "draft", "id": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71"}, {"name": "李罕之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：李罕之。", "biography": null, "status": "draft", "id": "3a3944bf-1d15-5b41-8fde-e3f51fbe285c"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "李存孝", "aliases": ["安敬思"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存孝，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "d25efb4e-74a3-5bab-b1e4-a79cee0716c3"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "邓季筠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：邓季筠。", "biography": null, "status": "draft", "id": "35e536de-74c3-5810-bcde-8670471465f0"}, {"name": "李谠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李谠，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "e76a9579-0dd7-58ad-b13d-e3c2f3015f30"}, {"name": "李重胤", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：李重胤。", "biography": null, "status": "draft", "id": "df895826-21be-5071-952c-7d7104d07b1f"}, {"name": "葛从周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的葛从周，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "26557449-8ad3-53a2-9cda-77849bf316c9"}, {"name": "朱崇节", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：朱崇节。", "biography": null, "status": "draft", "id": "7472b1fc-4a4c-5f2a-8c55-b214cf13a8e0"}, {"name": "康君立", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：康君立。", "biography": null, "status": "draft", "id": "8e06ad56-4fa8-5126-9253-2edc90d6439c"}, {"name": "李匡威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李匡威。", "biography": null, "status": "draft", "id": "bdc4b069-347f-5d1c-bafc-bbc5e7e2be44"}, {"name": "邢善益", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：邢善益。", "biography": null, "status": "draft", "id": "c70de661-ea85-5cb4-a6fc-e2456aa62404"}, {"name": "赫连铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：赫连铎。", "biography": null, "status": "draft", "id": "b54a0fc9-ea29-5e0d-9d2a-f8fe5be8cda9"}, {"name": "刘胡子", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：刘胡子。", "biography": null, "status": "draft", "id": "27a1f070-5dbc-5558-b0c4-1af0bddc0b80"}, {"name": "李存信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存信，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "31ad8087-ed47-5400-bf8a-47f2edb81920"}, {"name": "李嗣源", "aliases": ["李亶", "后唐明宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "biography": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "status": "draft", "id": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"name": "李仁宗", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：李仁宗。", "biography": null, "status": "draft", "id": "a8907b3a-29ad-5897-ac34-23ca89e9b03e"}, {"name": "张行周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：张行周。", "biography": null, "status": "draft", "id": "d7937816-eb52-5499-a3b9-c48f9c076381"}, {"name": "刘建锋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通