INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "杜孺休到官，钱镠密使沈粲害之", "start_year": 890, "end_year": 890, "time_original": "890年八月条；具体日未载", "dynasty": "唐", "description": "苏州刺史杜孺休到任，钱镠秘密命沈粲加害杜孺休。", "phases": [], "location_name": "苏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4b59502f-18a7-53a5-af02-f939610a5ebc"}, {"title": "李友拔苏州，沈粲归杭州后奔孙儒", "start_year": 890, "end_year": 890, "time_original": "890年八月条；具体日未载", "dynasty": "唐", "description": "杨行密将李友攻取苏州，沈粲返回杭州。钱镠欲归罪沈粲而杀之，沈粲逃投孙儒。", "phases": [], "location_name": "苏州、杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fba0c499-65cb-56f9-98cc-eca4eb7db32f"}, {"title": "王建退屯汉州", "start_year": 890, "end_year": 890, "time_original": "890年八月条；具体日未载", "dynasty": "唐", "description": "王建撤退驻军汉州。", "phases": [], "location_name": "汉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "87949ee5-c925-5f0c-98ec-480c460f82e8"}, {"title": "陈敬瑄设征督院逼富民供军", "start_year": 890, "end_year": 890, "time_original": "890年八月条；具体日未载", "dynasty": "唐", "description": "陈敬瑄搜括富民财产供军，置征督院，以桎梏棰楚逼民自报财产，对匿财虚报者急征；《通鉴》评有财者不聊生。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "c69eaf3f-7375-5590-851a-4404a478feb4"}, {"title": "李存孝奉李克用命援李罕之", "start_year": 890, "end_year": 890, "time_original": "890年八月后条；具体日未载", "dynasty": "唐", "description": "李罕之向李克用告急，李克用遣李存孝率骑兵救援。", "phases": [], "location_name": "泽州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "82303d01-f2fa-5650-a454-15decbce536b"}, {"title": "朱全忠驻军河阳", "start_year": 890, "end_year": 890, "time_original": "890年九月壬寅", "dynasty": "唐", "description": "朱全忠驻军河阳。", "phases": [], "location_name": "河阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "50446e9a-c54e-5225-b58f-63bc32a8d12f"}, {"title": "围泽州两军相讥的前事", "start_year": null, "end_year": null, "time_original": "汴军初围泽州至李存孝到援时；具体日未载", "dynasty": "唐", "description": "汴军初围泽州时讥李罕之倚河东，称沙陀将无处藏身。李存孝来援后率精骑绕汴寨，以寻穴者自称，挑战汴军。", "phases": [], "location_name": "泽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "afcb7bb2-f0a4-5014-8564-495b009a23ca"}, {"title": "李存孝生擒邓季筠", "start_year": 890, "end_year": 890, "time_original": "890年九月条；李存孝到援后", "dynasty": "唐", "description": "邓季筠率兵出战，被李存孝生擒。", "phases": [], "location_name": "泽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d11c2887-99d1-570e-9b56-5477f68f05d8"}, {"title": "李存孝李罕之败汴军于马牢山", "start_year": 890, "end_year": 890, "time_original": "890年九月条；擒邓季筠当夕后", "dynasty": "唐", "description": "李谠、李重胤当夕率众逃走，李存孝、李罕之追击，在马牢山大败汴军，追至怀州而还。", "phases": [], "location_name": "马牢山、怀州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "84722284-5590-5ea2-9232-b940d94c9e51"}, {"title": "葛从周朱崇节弃潞州", "start_year": 890, "end_year": 890, "time_original": "890年九月条；马牢山战后", "dynasty": "唐", "description": "李存孝再率兵攻潞州，葛从周、朱崇节弃城返回。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a2c677a7-7e85-590b-b925-774089034563"}, {"title": "朱全忠责败斩李谠李重胤", "start_year": 890, "end_year": 890, "time_original": "890年九月戊申", "dynasty": "唐", "description": "朱全忠庭责诸将败退之罪，斩李谠、李重胤后返回。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "56162399-7c96-5139-8f55-207a53c03967"}, {"title": "康君立领昭义，李存孝任汾州刺史", "start_year": 890, "end_year": 890, "time_original": "890年九月条；潞州战后", "dynasty": "唐", "description": "李克用以康君立为昭义留后，以李存孝为汾州刺史。《通鉴》记李存孝自认擒孙揆功大应镇昭义，因而愤恚，数日不食并纵意刑杀，始有叛李克用之志。", "phases": [], "location_name": "昭义、汾州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8647ad0f-e78b-5a82-b98e-b49c5a676990"}, {"title": "李匡威攻蔚州俘邢善益", "start_year": 890, "end_year": 890, "time_original": "890年九月条；具体日未载", "dynasty": "唐", "description": "李匡威攻蔚州，俘获刺史邢善益。", "phases": [], "location_name": "蔚州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "177cad9f-a750-58b6-9486-4284c1b490f6"}, {"title": "赫连铎攻遮虏平杀刘胡子", "start_year": 890, "end_year": 890, "time_original": "890年九月条；具体日未载", "dynasty": "唐", "description": "赫连铎率吐蕃、黠戛斯部众进攻遮虏平，杀其军使刘胡子。", "phases": [], "location_name": "遮虏平", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e02a71c6-1b18-59c4-8a29-d818b0e6e6d1"}, {"title": "李存信初败，李嗣源为副后破敌", "start_year": 890, "end_year": 890, "time_original": "890年九月条；遮虏平被攻后", "dynasty": "唐", "description": "李克用先遣李存信出击，未能获胜；再命李嗣源为李存信副手，遂击败敌军。", "phases": [], "location_name": "遮虏平方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8c1e1cb6-0570-5a3d-8710-210149e4944e"}, {"title": "李克用继进败李匡威赫连铎", "start_year": 890, "end_year": 890, "time_original": "890年九月条；李嗣源击破之后", "dynasty": "唐", "description": "李克用以大军随后，李匡威、赫连铎败走，李克用军俘获李匡威之子、武州刺史李仁宗及赫连铎之婿，书载俘斩万计。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "0a173ffa-2677-51f5-b250-e5eea79c149c"}, {"title": "李嗣源讥诸将夸口勇略", "start_year": null, "end_year": null, "time_original": "诸将相会时；具体年日未载", "dynasty": "唐", "description": "《通鉴》记诸将相会各夸勇略，李嗣源默然，后称诸将以口击贼、自己以手击贼，诸将惭而止；书中评李嗣源谨重廉俭。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "a826041e-4fba-5ddf-96d4-630ac69a04e1"}, {"title": "杨行密任张行周常州制置使", "start_year": 890, "end_year": 890, "time_original": "890年九月条；闰月前", "dynasty": "唐", "description": "杨行密以其将张行周为常州制置使。", "phases": [], "location_name": "常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5b737a03-101d-5ff8-95f4-58abe8d66e6e"}, {"title": "刘建锋取常州杀张行周并围苏州", "start_year": 890, "end_year": 890, "time_original": "890年闰月；承九月条", "dynasty": "唐", "description": "孙儒遣刘建锋攻取常州，杀张行周，随后围苏州。", "phases": [], "location_name": "常州、苏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "51fa3570-012e-5f9a-9760-d78599a5fccf"}]'::jsonb)
